def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = []
        for start, end in intervals:
            if start >= end:
                continue
            if merged and start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []
    if not b_merged:
        return a_merged

    result = []
    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]
        for b_start, b_end in b_merged:
            next_current = []
            for curr_start, curr_end in current:
                if b_end <= curr_start or b_start >= curr_end:
                    next_current.append([curr_start, curr_end])
                else:
                    if curr_start < b_start:
                        next_current.append([curr_start, b_start])
                    if curr_end > b_end:
                        next_current.append([b_end, curr_end])
            current = next_current
        result.extend(current)

    return sorted(result)

